-- Generated by `pnpm --filter @carbon/database authz migration` from packages/database/src/authz. Do not edit.

-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.check_employee_type_change(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Moving a person to another employee type changes their access, so it goes
  -- through writeAccessGrants (audit, claims cache). Reads the request role: the
  -- dispatcher runs this as the owner, so current_user is never an API role.
  IF p_operation = 'UPDATE'
     AND (p_new->>'employeeTypeId') IS DISTINCT FROM (p_old->>'employeeTypeId')
     AND current_setting('role', true) IN ('anon', 'authenticated') THEN
    RAISE EXCEPTION 'An employee''s type can only be changed by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;

-- permission
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'permission' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'permission');
  END LOOP;
END
$authz$;
ALTER TABLE public."permission" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."permission" FOR SELECT USING ((("userId" IS NOT NULL AND "companyId" = ANY ((SELECT get_companies_with_employee_permission('users.accounts_update'))::text[])) OR ("employeeTypeId" IS NOT NULL AND "companyId" = ANY ((SELECT get_companies_with_module_view(ARRAY['users']::text[], '{}'::text[]))::text[])) OR ("apiKeyId" IS NOT NULL AND "companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.apiKeys_view'))::text[]))));

-- event triggers (packages/database/src/event-system/attachments.ts)
SET lock_timeout = '5s';
SELECT set_event_triggers('employee', ARRAY['check_employee_type_change', 'sync_update_employee_type_membership']::text[], ARRAY['sync_add_employee_to_type_group']::text[], true, ARRAY['broadcast_table_changes', 'log_table_changes']::text[]);
RESET lock_timeout;
